def _kpp(data: torch.Tensor, k: int, sample_size: int = -1):
    if sample_size is not None and sample_size > 0:
        data = data[torch.randint(0, int(data.shape[0]), [min(100000, data.shape[0])], device=data.device)]
    dims = data.shape[1] if len(data.shape) > 1 else 1
    init = torch.zeros((k, dims)).to(data.device)
    r = torch.distributions.uniform.Uniform(0, 1)
    for i in range(k):
        if i == 0:
            init[i, :] = data[torch.randint(data.shape[0], [1])]
        else:
            D2 = torch.cdist(init[:i, :][None, :], data[None, :], p=2)[0].amin(dim=0)
            probs = D2 / torch.sum(D2)
            cumprobs = torch.cumsum(probs, dim=0)
            init[i, :] = data[torch.searchsorted(cumprobs, r.sample([1]).to(data.device))]
    return init

class KMeans:
    def __init__(self, n_clusters, max_iter=300, tol=0.0001, verbose=0, mode="euclidean", init_method="kmeans++",
                 minibatch=None, n_init=10, algorithm=None, device=None):
        self.n_clusters = n_clusters
        self.max_iter = max_iter
        self.tol = tol
        self.verbose = verbose
        self.mode = mode
        self.init_method = init_method
        self.device = device if device is not None else 'cpu'
        self.cluster_centers_ = None
        self.labels_ = None
        self.n_init = n_init if n_init is not None else 1

    @staticmethod
    def cos_sim(a, b):
        a_norm = a.norm(dim=-1, keepdim=True)
        b_norm = b.norm(dim=-1, keepdim=True)
        a = a / (a_norm + 1e-8)
        b = b / (b_norm + 1e-8)
        return a @ b.transpose(-2, -1)

    @staticmethod
    def euc_sim(a, b):
        return 2 * a @ b.transpose(-2, -1) - (a ** 2).sum(dim=1)[..., :, None] - (b ** 2).sum(dim=1)[..., None, :]

    def max_sim(self, a, b):
        if self.mode == 'cosine':
            sim_func = self.cos_sim
        elif self.mode == 'euclidean':
            sim_func = self.euc_sim
        sim = sim_func(a, b)
        max_sim_v, max_sim_i = sim.max(dim=-1)
        return max_sim_v, max_sim_i

    def fit_predict(self, X, sample_weight=None, centroids=None):
        X = X.to(self.device)
        if sample_weight is None:
            sample_weight = torch.ones(X.shape[0], device=self.device, dtype=X.dtype)
        else:
            sample_weight = sample_weight.to(self.device)
        cluster_centers_ = centroids
        for i in range(self.max_iter):
            x = X
            sim_score, closest = self.max_sim(a=x, b=cluster_centers_)
            matched_clusters, counts = closest.unique(return_counts=True)
            unmatched_clusters_mask = torch.ones(self.n_clusters, dtype=torch.bool, device=self.device)
            unmatched_clusters_mask[matched_clusters.long()] = False
            unmatched_clusters = torch.where(unmatched_clusters_mask)[0]
            while unmatched_clusters.shape[0] > 0:
                worst_x = x[sim_score.argmin(dim=0)]
                cluster_centers_[unmatched_clusters[0]] = worst_x
                sim_score, closest = self.max_sim(a=x, b=cluster_centers_)
                matched_clusters, counts = closest.unique(return_counts=True)
                unmatched_clusters_mask = torch.ones(self.n_clusters, dtype=torch.bool, device=self.device)
                unmatched_clusters_mask[matched_clusters.long()] = False
                unmatched_clusters = torch.where(unmatched_clusters_mask)[0]
            c_grad = torch.zeros_like(cluster_centers_)
            expanded_closest = closest[None].expand(self.n_clusters, -1)
            mask = (expanded_closest == torch.arange(self.n_clusters, device=self.device)[:, None]).to(X.dtype)
            mask = mask * sample_weight[None, :]
            sum_mask = mask.sum(-1)[..., :, None]
            c_grad = torch.where(sum_mask > 0, mask @ x / sum_mask, c_grad)
            error = (c_grad - cluster_centers_).pow(2).sum()
            lr = 1
            cluster_centers_ = cluster_centers_ * (1 - lr) + c_grad * lr
            if error <= self.tol:
                break
        return cluster_centers_.detach(), closest.detach(), sim_score.sum().neg().detach()

    def fit(self, X, sample_weight=None, centroids=None):
        self.cluster_centers_, self.labels_, self.inertia_ = [], [], []
        if centroids is None:
            if self.init_method == 'kmeans++':
                 initial_centroids = [_kpp(X, self.n_clusters) for _ in range(self.n_init)]
            else:
                 initial_centroids = [X[torch.randint(0, X.shape[0], size=[self.n_clusters], device=X.device)] for _ in range(self.n_init)]
        else:
            initial_centroids = centroids if isinstance(centroids, list) else [centroids]
        if not all(isinstance(c, torch.Tensor) for c in initial_centroids):
            initial_centroids = [torch.tensor(c, dtype=X.dtype, device=X.device) for c in initial_centroids]
        for i in range(self.n_init):
            cluster_centers, labels, inertia = self.fit_predict(X, sample_weight, initial_centroids[i])
            self.cluster_centers_.append(cluster_centers)
            self.labels_.append(labels)
            self.inertia_.append(inertia)
        best_cluster_idx = torch.argmin(torch.stack(self.inertia_))
        self.cluster_centers_ = self.cluster_centers_[best_cluster_idx].cpu().numpy()
        self.labels_ = self.labels_[best_cluster_idx].cpu().numpy()
        self.inertia_ = self.inertia_[best_cluster_idx].cpu().numpy()
        return self

class SimATTA(AlgBase):
    def __init__(self, config):
        super(SimATTA, self).__init__(config)
        self.teacher = copy.deepcopy(self.model.to('cpu'))
        self.model.to(config.device)
        self.teacher.to(config.device)
        self.update_teacher(0)
        self.budgets = 0
        self.anchors = None
        self.source_anchors = None
        self.buffer = []
        self.n_clusters = 10
        self.nc_increase = self.config.atta.SimATTA.nc_increase
        self.source_n_clusters = 100
        self.cold_start = self.config.atta.SimATTA.cold_start
        self.consistency_weight = 0
        self.alpha_teacher = 0
        self.accumulate_weight = True
        self.weighted_entropy = 'both'
        self.aggressive = True
        self.beta = self.config.atta.SimATTA.beta
        self.alpha = 0.2
        self.target_cluster = True if self.config.atta.SimATTA.target_cluster else False
        self.LE = True if self.config.atta.SimATTA.LE else False
        self.vis_round = 0

    def __call__(self, *args, **kwargs):
        self.enable_bn(self.model)
        for adapt_id in self.config.dataset.test_envs[1:]:
            self.adapt_on_env(self.fast_loader, adapt_id)

    def update_teacher(self, alpha_teacher):
        for t_param, s_param in zip(self.teacher.parameters(), self.model.parameters()):
            t_param.data[:] = alpha_teacher * t_param[:].data[:] + (1 - alpha_teacher) * s_param[:].data[:]
        if not self.config.model.freeze_bn:
            for tm, m in zip(self.teacher.modules(), self.model.modules()):
                if isinstance(m, (torch.nn.BatchNorm1d, torch.nn.BatchNorm2d)):
                    tm.running_mean = alpha_teacher * tm.running_mean + (1 - alpha_teacher) * m.running_mean
                    tm.running_var = alpha_teacher * tm.running_var + (1 - alpha_teacher) * m.running_var

    @torch.enable_grad()
    def cluster_train(self, target_anchors, source_anchors):
        self.model.train()
        source_loader = iter([(torch.randn(16,3,224,224), torch.randint(0,self.config.dataset.num_classes,(16,))) for _ in range(5)])
        target_loader = iter([(torch.randn(16,3,224,224), torch.randint(0,self.config.dataset.num_classes,(16,))) for _ in range(5)])
        alpha = target_anchors.num_elem() / (target_anchors.num_elem() + source_anchors.num_elem())
        if source_anchors.num_elem() < self.cold_start:
            alpha = min(0.2, alpha)
        ST_loader = iter(zip(source_loader, target_loader))
        optimizer = torch.optim.SGD(self.model.parameters(), lr=self.config.atta.SimATTA.lr, momentum=0.9)
        loss_window = []
        tol = 0
        lowest_loss = float('inf')
        for i, ((S_data, S_targets), (T_data, T_targets)) in enumerate(ST_loader):
            S_data, S_targets = S_data.to(self.config.device), S_targets.to(self.config.device)
            T_data, T_targets = T_data.to(self.config.device), T_targets.to(self.config.device)
            L_T = self.one_step_train(S_data, S_targets, T_data, T_targets, alpha, optimizer)
            if len(loss_window) < self.config.atta.SimATTA.stop_tol:
                loss_window.append(L_T.item())
            else:
                mean_loss = np.mean(loss_window)
                tol += 1
                if mean_loss < lowest_loss:
                    lowest_loss = mean_loss
                    tol = 0
                if tol > 1:
                    break
                loss_window = []
            if i > self.config.atta.SimATTA.steps:
                break

    def one_step_train(self, S_data, S_targets, T_data, T_targets, alpha, optimizer):
        L_S = self.config.metric.loss_func(self.model(S_data), S_targets)
        L_T = self.config.metric.loss_func(self.model(T_data), T_targets)
        loss = (1 - alpha) * L_S + alpha * L_T
        optimizer.zero_grad()
        loss.backward()
        optimizer.step()
        return L_T

    def softmax_entropy(self, x: torch.Tensor, y: torch.Tensor = None) -> torch.Tensor:
        if y is None:
            if x.shape[1] == 1:
                x = torch.cat([x, -x], dim=1)
            return -(x.softmax(1) * x.log_softmax(1)).sum(1)
        else:
            return - 0.5 * (x.softmax(1) * y.log_softmax(1)).sum(1) - 0.5 * (y.softmax(1) * x.log_softmax(1)).sum(1)

    def update_anchors(self, anchors, data, target, feats, weight):
        if anchors is None:
            anchors = Munch()
            anchors.data = data
            anchors.target = target
            anchors.feats = feats
            anchors.weight = weight
            anchors.num_elem = lambda: len(anchors.data)
        else:
            anchors.data = torch.cat([anchors.data, data])
            anchors.target = torch.cat([anchors.target, target])
            anchors.feats = torch.cat([anchors.feats, feats])
            anchors.weight = torch.cat([anchors.weight, weight])
        return anchors

    def update_anchors_feats(self, anchors):
        self.model.eval()
        if anchors.num_elem() > 0:
            anchors.feats = self.model[0](anchors.data.to(self.config.device)).cpu().detach()
        else:
            anchors.feats = torch.tensor([])
        return anchors

    def adapt_on_env(self, loader, env_id):
        acc = 0
        for data, target in loader[env_id]:
            data, target = data.to(self.config.device), target.to(self.config.device)
            outputs, closest, self.anchors = self.sample_select(self.model, data, target, self.anchors,
                                                                int(self.n_clusters), 1,
                                                                ent_bound=self.config.atta.SimATTA.eh,
                                                                incremental_cluster=self.target_cluster)
            acc += self.config.metric.score_func(target, outputs).item() * data.shape[0]
            if self.LE:
                _, _, self.source_anchors = self.sample_select(self.teacher, data, target, self.source_anchors,
                                                                self.source_n_clusters, 0,
                                                                use_pseudo_label=True,
                                                                ent_bound=self.config.atta.SimATTA.el,
                                                                incremental_cluster=False)
            else:
                self.source_anchors = self.update_anchors(None, torch.tensor([]), None, None, None)

            if not self.target_cluster:
                self.n_clusters = 0

            self.budgets += len(closest)
            self.n_clusters += self.nc_increase
            self.source_n_clusters += 1
            if self.source_anchors.num_elem() > 0:
                self.cluster_train(self.anchors, self.source_anchors)
            else:
                self.cluster_train(self.anchors, self.anchors)
            self.anchors = self.update_anchors_feats(self.anchors)
        return acc

    def sample_select(self, model, data, target, anchors, n_clusters, ent_beta, use_pseudo_label=False, ent_bound=1e-2, incremental_cluster=False):
        model.eval()
        feats = model[0](data)
        outputs = model[1](feats)
        pseudo_label = outputs.argmax(1).cpu().detach()
        data_cpu = data.cpu().detach()
        feats_cpu = feats.cpu().detach()
        target_cpu = target.cpu().detach()
        entropy = self.softmax_entropy(outputs).cpu()

        if not incremental_cluster:
            entropy_np = entropy.numpy()
            if ent_beta == 0:
                closest_indices_in_batch = np.argsort(entropy_np)[: n_clusters]
                closest_indices_in_batch = closest_indices_in_batch[entropy_np[closest_indices_in_batch] < ent_bound]
            elif ent_beta == 1:
                closest_indices_in_batch = np.argsort(entropy_np)[- n_clusters:]
                closest_indices_in_batch = closest_indices_in_batch[entropy_np[closest_indices_in_batch] >= ent_bound]
            else:
                raise NotImplementedError
            weights = torch.zeros(len(closest_indices_in_batch), dtype=torch.float)
        else:
            if ent_beta == 0:
                sample_choice = entropy < ent_bound
            elif ent_beta == 1:
                sample_choice = entropy >= ent_bound
            else:
                raise NotImplementedError
            data_filtered = data_cpu[sample_choice]
            target_filtered = target_cpu[sample_choice]
            feats_filtered = feats_cpu[sample_choice]
            pseudo_label_filtered = pseudo_label[sample_choice]

            if anchors and anchors.num_elem() > 0:
                feats4cluster = torch.cat([anchors.feats, feats_filtered])
                sample_weight = torch.cat([anchors.weight, torch.ones(len(feats_filtered), dtype=torch.float)])
            else:
                feats4cluster = feats_filtered
                sample_weight = torch.ones(len(feats_filtered), dtype=torch.float)

            if self.config.atta.gpu_clustering:
                kmeans = KMeans(n_clusters=n_clusters, n_init=10, device=self.config.device).fit(
                    feats4cluster.to(self.config.device), sample_weight=sample_weight.to(self.config.device))
                dist_matrix = torch.cdist(torch.tensor(kmeans.cluster_centers_, device=feats4cluster.device), feats4cluster)
                raw_closest = dist_matrix.argmin(dim=1).cpu().numpy()
                kmeans_labels = kmeans.labels_
            else:
                kmeans = KMeans(n_clusters=n_clusters, n_init=10, algorithm='elkan', device='cpu').fit(feats4cluster, sample_weight=sample_weight)
                dist_matrix = torch.cdist(torch.tensor(kmeans.cluster_centers_), feats4cluster)
                raw_closest = dist_matrix.argmin(dim=1).cpu().numpy()
                kmeans_labels = kmeans.labels_

            if anchors and anchors.num_elem() > 0:
                num_anchors = anchors.num_elem()
                prev_anchor_cluster = torch.tensor(kmeans_labels[:num_anchors], dtype=torch.long)
                if self.accumulate_weight:
                    pass
                anchored_cluster_mask = torch.zeros(len(raw_closest), dtype=torch.bool).index_fill_(0,
                                                                                                    prev_anchor_cluster.unique().long(),
                                                                                                    True)
                new_cluster_mask = ~ anchored_cluster_mask
                closest_indices_in_feats_filtered = raw_closest[new_cluster_mask] - num_anchors
                closest_indices_in_feats_filtered = closest_indices_in_feats_filtered[closest_indices_in_feats_filtered >= 0]
                weights = torch.tensor(kmeans_labels).unique(return_counts=True)[1][new_cluster_mask]
                weights = weights[closest_indices_in_feats_filtered >= 0]
            else:
                num_anchors = 0
                closest_indices_in_feats_filtered = raw_closest
                weights = torch.tensor(kmeans_labels).unique(return_counts=True)[1]
            selected_data = data_filtered[closest_indices_in_feats_filtered]
            selected_target = pseudo_label_filtered[closest_indices_in_feats_filtered] if use_pseudo_label else target_filtered[closest_indices_in_feats_filtered]
            selected_feats = feats_filtered[closest_indices_in_feats_filtered]
            anchors = self.update_anchors(anchors, selected_data, selected_target, selected_feats, weights)
            closest_indices_in_batch = closest_indices_in_feats_filtered

        return outputs, closest_indices_in_batch, anchors

    def enable_bn(self, model):
        if not self.config.model.freeze_bn:
            for m in model.modules():
                if isinstance(m, (torch.nn.BatchNorm1d, torch.nn.BatchNorm2d)):
                    m.momentum = 0.1

import torch
import torch.nn as nn
import torch.jit
from copy import deepcopy
import torch.optim as optim

class Tent(nn.Module):
    def __init__(self, model, optimizer, steps=1, episodic=False):
        super().__init__()
        self.model = model
        self.optimizer = optimizer
        self.steps = steps
        assert steps > 0, "tent requires >= 1 step(s) to forward and update"
        self.episodic = episodic
        self.model_state, self.optimizer_state = copy_model_and_optimizer(self.model, self.optimizer)

    def forward(self, x):
        if self.episodic:
            self.reset()
        for _ in range(self.steps):
            outputs = forward_and_adapt(x, self.model, self.optimizer)
        return outputs

    def reset(self):
        if self.model_state is None or self.optimizer_state is None:
            raise Exception("cannot reset without saved model/optimizer state")
        load_model_and_optimizer(self.model, self.optimizer, self.model_state, self.optimizer_state)

@torch.jit.script
def softmax_entropy(x: torch.Tensor) -> torch.Tensor:
    return -(x.softmax(1) * x.log_softmax(1)).sum(1)

@torch.enable_grad()
def forward_and_adapt(x, model, optimizer):
    outputs = model(x)
    loss = softmax_entropy(outputs).mean(0)
    loss.backward()
    optimizer.step()
    optimizer.zero_grad()
    return outputs

def collect_params(model):
    params = []
    names = []
    for nm, m in model.named_modules():
        if isinstance(m, nn.BatchNorm2d):
            for np, p in m.named_parameters():
                if np in ['weight', 'bias']: 
                    params.append(p)
                    names.append(f"{nm}.{np}")
    return params, names

def copy_model_and_optimizer(model, optimizer):
    model_state = deepcopy(model.state_dict())
    optimizer_state = deepcopy(optimizer.state_dict())
    return model_state, optimizer_state

def load_model_and_optimizer(model, optimizer, model_state, optimizer_state):
    model.load_state_dict(model_state, strict=True)
    optimizer.load_state_dict(optimizer_state)

def configure_model(model):
    model.train()
    model.requires_grad_(False)
    for m in model.modules():
        if isinstance(m, nn.BatchNorm2d):
            m.requires_grad_(True)
            m.track_running_stats = False
            m.running_mean = None
            m.running_var = None
    return model

def setup_tent(model, cfg):
    model = configure_model(model)
    params, param_names = collect_params(model)
    optimizer = setup_optimizer(params, cfg)
    tent_model = Tent(model, optimizer,
                           steps=cfg.OPTIM.STEPS,
                           episodic=cfg.MODEL.EPISODIC)
    return tent_model

def setup_optimizer(params, cfg):
    if cfg.OPTIM.METHOD == 'Adam':
        return optim.Adam(params,
                    lr=cfg.OPTIM.LR,
                    betas=(cfg.OPTIM.BETA, 0.999),
                    weight_decay=cfg.OPTIM.WD)
    elif cfg.OPTIM.METHOD == 'SGD':
        return optim.SGD(params,
                   lr=cfg.OPTIM.LR,
                   momentum=cfg.OPTIM.MOMENTUM,
                   dampening=cfg.OPTIM.DAMPENING,
                   weight_decay=cfg.OPTIM.WD,
                   nesterov=cfg.OPTIM.NESTEROV)
    else:
        raise NotImplementedError

