    def __init__(self, C):
        super().__init__(); self.g = nn.Parameter(torch.ones(C)); self.b = nn.Parameter(torch.zeros(C))
    def forward(self,x,delta):
        g,b = self.g+delta[:,0], self.b+delta[:,1]
        return g.view(1,-1,1,1)*x + b.view(1,-1,1,1)

